const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const flintHills = ee.Geometry.Point([-96.5, 38.5]).buffer(50000); // 50km radius around Flint Hills
  const date1 = '2023-03-19';
  const date2 = '2023-04-08';

  // 2. Data Acquisition & Check
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Get images for March 19
  const col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(flintHills)
    .filterDate(date1, ee.Date(date1).advance(3, 'day'))
    .map(maskS2clouds);

  const size1 = await col1.size().getInfo();
  console.log(`March 19 Images: ${size1}`);

  if (size1 === 0) {
    console.log("No data for March 19, 2023.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get images for April 8
  const col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(flintHills)
    .filterDate(date2, ee.Date(date2).advance(3, 'day'))
    .map(maskS2clouds);

  const size2 = await col2.size().getInfo();
  console.log(`April 8 Images: ${size2}`);

  if (size2 === 0) {
    console.log("No data for April 8, 2023.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate NBR and detect burns
  function calculateNBR(image) {
    const nir = image.select('B8');
    const swir = image.select('B12');
    const nbr = nir.subtract(swir).divide(nir.add(swir)).rename('NBR');
    return image.addBands(nbr);
  }

  const img1 = col1.map(calculateNBR).median();
  const img2 = col2.map(calculateNBR).median();

  // Burn scars typically have NBR < 0.1 (lower values indicate recent burns)
  const burnThreshold = 0.1;
  const burns1 = img1.select('NBR').lt(burnThreshold);
  const burns2 = img2.select('NBR').lt(burnThreshold);

  // 4. Calculate burn scar areas
  const count1 = await burns1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: flintHills,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const count2 = await burns2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: flintHills,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`March 19 burn pixels: ${count1}`);
  console.log(`April 8 burn pixels: ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === null || count2 === null || isNaN(count1) || isNaN(count2)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (count1 === 0 && count2 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  console.log(`Burn extent change: ${((count2 - count1) / Math.max(count1, 1) * 100).toFixed(1)}%`);

  if (count2 > count1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
